def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    WALL, PLUG, PAINT = 7, 9, 8
    def is_open(y, x):
        return 0 <= y < H and 0 <= x < W and g[y, x] in (0, PLUG)

    # find opening on a border: 0 cell flanked by walls along the border
    start = None
    for y in range(H):
        for x in range(W):
            if y not in (0, H - 1) and x not in (0, W - 1):
                continue
            if g[y, x] != 0:
                continue
            if y in (0, H - 1):
                if 0 < x < W - 1 and g[y, x - 1] == WALL and g[y, x + 1] == WALL:
                    start = (y, x)
            elif 0 < y < H - 1 and g[y - 1, x] == WALL and g[y + 1, x] == WALL:
                start = (y, x)
            if start:
                break
        if start:
            break
    if start is None:
        return g

    visited = {start}
    cur = start
    g[cur] = PAINT
    prev_dir = None
    while True:
        nxt = None
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = cur[0] + dy, cur[1] + dx
            if (ny, nx) not in visited and is_open(ny, nx):
                nxt = (ny, nx, dy, dx)
                break
        if nxt is None:
            break
        ny, nx, dy, dx = nxt
        if prev_dir is not None and (dy, dx) != prev_dir:
            emit(g, f"Straight run of the corridor painted with 8; the path turns at {cur}.")
        if g[ny, nx] == PLUG:
            by, bx = ny + dy, nx + dx
            if not (0 <= by < H and 0 <= bx < W and g[by, bx] == 0):
                emit(g, f"The 9 at {(ny, nx)} sits where the corridor turns, so painting stops before it.")
                break
        g[ny, nx] = PAINT
        visited.add((ny, nx))
        cur = (ny, nx)
        prev_dir = (dy, dx)
    emit(g, "Final: corridor painted with 8 from the border opening.")
    return g
